import base64, hashlib, io, zipfile, os, subprocess, sys, pathlib
blob=base64.b64decode('')
assert hashlib.sha256(blob).hexdigest()=='7a354166d1ad4e13f1032e0911955b053e0e41b8cc1a70b1ce227694ae393e26'
root=pathlib.Path('/content/mcf449v2') if pathlib.Path('/content').exists() else pathlib.Path('/tmp/mcf449v2')
root.mkdir(exist_ok=True,parents=True)
with zipfile.ZipFile(io.BytesIO(blob)) as zip_file:
    assert all('..' not in pathlib.Path(item.filename).parts for item in zip_file.infolist())
    zip_file.extractall(root)
os.environ['DEMO_MODE']='1'
subprocess.run([sys.executable,'-m','pip','install','-q','-r',str(root/'requirements.txt')],check=True)
result=subprocess.run([sys.executable,'-m','pytest','-q',str(root/'tests')],cwd=str(root),capture_output=True,text=True)
print(result.stdout[-3000:])
assert result.returncode==0,result.stderr[-1500:]
print('MCF449_V2_CPU_COLAB_PASS')
